function openAccountsPage(subpage) {
  currentModule = 'accounts';
  currentAccountsView = 'main';
  currentAccountsSubpage = subpage || 'sales';
  activeColumnFilters = {};
  updateURL();
  renderApp();
  showToast(`Navigated to Accounts`);
}

